import asyncio
import os
from pathlib import Path


class LocalDiskStorage:
    """Files under one directory, so nothing needs a cloud account. DuckDB reads them directly."""

    name = "local"

    def __init__(self, root: str) -> None:
        self.root = Path(root).resolve()

    def path(self, key: str) -> Path:
        path = (self.root / key).resolve()
        # Keys are generated by the app, but never let one escape the storage root.
        if not path.is_relative_to(self.root):
            raise ValueError(f"Storage key escapes the storage root: {key}")
        return path

    async def put(self, key: str, data: bytes) -> None:
        """Writes to a temporary name, then renames: a reader never sees a half-written file."""
        path = self.path(key)
        await asyncio.to_thread(path.parent.mkdir, parents=True, exist_ok=True)
        temporary = path.with_name(f".{path.name}.tmp")
        await asyncio.to_thread(temporary.write_bytes, data)
        await asyncio.to_thread(os.replace, temporary, path)

    async def get(self, key: str) -> bytes:
        return await asyncio.to_thread(self.path(key).read_bytes)

    async def list(self, prefix: str) -> list[str]:
        base = self.path(prefix)

        def walk() -> list[str]:
            if not base.exists():
                return []
            return sorted(
                str(p.relative_to(self.root))
                for p in base.rglob("*")
                if p.is_file() and not p.name.startswith(".")
            )

        return await asyncio.to_thread(walk)

    async def delete(self, key: str) -> None:
        await asyncio.to_thread(self.path(key).unlink, missing_ok=True)
